import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        Map<String, Integer> frequency = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String password = fs.next();
            frequency.put(password, frequency.getOrDefault(password, 0) + 1);
        }

        long answer = 0;
        for (Map.Entry<String, Integer> entry : frequency.entrySet()) {
            String password = entry.getKey();
            int count = entry.getValue();

            Set<String> substrings = new HashSet<>();
            for (int start = 0; start < password.length(); start++) {
                for (int end = start + 1; end <= password.length(); end++) {
                    substrings.add(password.substring(start, end));
                }
            }

            long matchingUsers = 0;
            for (String substring : substrings) {
                matchingUsers += frequency.getOrDefault(substring, 0);
            }

            answer += (long) count * (matchingUsers - 1);
        }

        System.out.println(answer);
    }

    private static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
